
@import url('https://fonts.googleapis.com/css2?family=Luckiest+Guy&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@700&display=swap');
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700;800&display=swap');
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: Arial, Helvetica, sans-serif;
  background: linear-gradient(135deg, #f7c600, #ffdf3a);
  color: #111;
  overflow: hidden;
  position: relative;
  isolation: isolate;
}

body::before,
body::after {
  content: "";
  position: fixed;
  inset: -14%;
  pointer-events: none;
  z-index: 0;
}

body::before {
  background:
    radial-gradient(circle at 14% 18%, rgba(255,255,255,.28) 0 10%, transparent 28%),
    radial-gradient(circle at 82% 16%, rgba(255,236,158,.34) 0 11%, transparent 30%),
    radial-gradient(circle at 80% 82%, rgba(255,170,0,.26) 0 12%, transparent 34%),
    radial-gradient(circle at 18% 86%, rgba(255,255,255,.18) 0 10%, transparent 30%),
    radial-gradient(circle at 52% 48%, rgba(255,214,51,.16) 0 15%, transparent 38%);
  filter: blur(12px);
  opacity: .95;
  animation: sfkBackgroundFloat 20s ease-in-out infinite alternate;
}

body::after {
  inset: 0;
  background:
    linear-gradient(115deg, rgba(255,255,255,.2), rgba(255,255,255,0) 36%),
    radial-gradient(circle at center, rgba(255,255,255,.08) 0 1px, transparent 1.2px);
  background-size: 100% 100%, 22px 22px;
  opacity: .38;
  mix-blend-mode: soft-light;
  animation: sfkBackgroundDrift 26s linear infinite;
}

@keyframes sfkBackgroundFloat {
  0% {
    transform: translate3d(-2.5%, -1.5%, 0) scale(1);
  }
  50% {
    transform: translate3d(1.5%, 2%, 0) scale(1.04);
  }
  100% {
    transform: translate3d(3%, -2%, 0) scale(1.08);
  }
}

@keyframes sfkBackgroundDrift {
  0% {
    transform: translate3d(0, 0, 0);
  }
  50% {
    transform: translate3d(-14px, 12px, 0);
  }
  100% {
    transform: translate3d(14px, -10px, 0);
  }
}

.app {
  height: 100vh;
  padding: 8px;
  display: grid;
  grid-template-rows: auto 145px 1fr auto;
  gap: 7px;
  position: relative;
  z-index: 1;
}

/* TOP BAR */
.topbar {
  display: grid;
  grid-template-columns: 1.05fr 1.35fr auto;
  align-items: center;
  gap: 12px;
  background: #111;
  color: white;
  padding: 9px 16px;
  border-radius: 16px;
  border: 3px solid white;
  box-shadow: 4px 4px 0 rgba(0,0,0,.35);
  position: relative;
}

.brandBox {
  min-width: 0;
  padding-right: 55px;
}

.topbarHeart {
  position: absolute;
  left: 32.5%;
  top: 55%;
  transform: translate(-50%, -50%);
  font-size: clamp(4.5rem, 4.5vw, 4.8rem);
  line-height: 1;
  z-index: 3;
  pointer-events: none;
}

.topbar h1 {
  font-size: clamp(1.7rem, 2.7vw, 2.6rem);
  line-height: 1;
}

.topbar p {
  margin-top: 4px;
  color: #ffd700;
  font-size: clamp(.82rem, 1vw, 1rem);
}

/* TOP DAILY QUOTE */
.topQuoteBox {
  background: rgba(255, 215, 0, .12);
  border: 2px solid rgba(255, 215, 0, .75);
  border-radius: 14px;
  padding: 7px 12px;
  text-align: center;
  min-width: 0;
}

.quoteLabel {
  display: inline-block;
  background: #ffd700;
  color: #111;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: .62rem;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .7px;
  margin-bottom: 3px;
}

.topQuoteBox #dailyQuote {
  color: white;
  font-size: clamp(.85rem, 1.05vw, 1rem);
  font-weight: 800;
  line-height: 1.15;
  margin: 0;
}

.topQuoteBox #quoteAuthor {
  display: block;
  margin-top: 2px;
  color: #ffd700;
  font-size: .72rem;
  font-weight: 800;
}

.timeBox {
  background: #ffd700;
  color: #111;
  padding: 8px 14px;
  border-radius: 13px;
  text-align: right;
  min-width: 230px;
}

.timeBox h2 {
  font-size: clamp(1.6rem, 2.8vw, 2.5rem);
  line-height: 1;
}

.timeBox p {
  font-size: clamp(.8rem, 1vw, .95rem);
  color: #111;
}

/* CURRENT / NEXT / PRAYER / BIRTHDAY */
.heroGrid {
  display: grid;
  grid-template-columns: 1.15fr 1.15fr .85fr .9fr;
  gap: 7px;
  height: 145px;
  align-items: stretch;
}

.card {
  background: rgba(255,255,255,.97);
  border: 3px solid #111;
  border-radius: 16px;
  padding: 10px 12px;
  box-shadow: 4px 4px 0 #111;
  min-height: 0;
}

.current,
.next,
.prayer,
.birthdayCard {
  padding: 8px 12px;
}

.label {
  font-size: clamp(.75rem, .95vw, .9rem);
  text-transform: uppercase;
  font-weight: 800;
  letter-spacing: 1px;
  color: #555;
  margin-bottom: 2px;
}

.current,
.next {
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.current {
  background: #111;
  color: white;
}

.current .label {
  color: #ffd700;
}

.next {
  background: #fff7c7;
}

.current h2,
.next h2 {
  font-size: clamp(1.25rem, 2vw, 1.85rem);
  line-height: 1.05;
  margin-bottom: 6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.current p:last-child,
.next p:last-child {
  font-size: clamp(.82rem, 1vw, .98rem);
  line-height: 1.15;
  margin-top: 2px;
}

.next #nextDetails,
#nextDetails {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.countdown {
  margin-top: 6px;
  background: rgba(0, 0, 0, .44);
  color: #fff;
  border-radius: 999px;
  padding: 4px 9px;
  width: fit-content;
  max-width: 100%;
  font-size: clamp(.78rem, .95vw, .95rem);
  line-height: 1;
  white-space: nowrap;
  font-weight: 900;
}

.currentCountdown {
  margin-top: 6px;
  background: rgba(255, 215, 0, .95);
  color: #111;
  border: 2px solid rgba(0,0,0,.35);
  border-radius: 999px;
  padding: 4px 9px;
  width: fit-content;
  max-width: 100%;
  font-size: clamp(.78rem, .95vw, .95rem);
  line-height: 1;
  white-space: nowrap;
  font-weight: 900;
}


/* PRAYER LEADER + CLEANERS */
.prayerLeaderLink,
.prayerLeaderLink:visited,
.prayerLeaderLink:hover,
.prayerLeaderLink:active,
.prayerLeaderLink:focus {
  display: block;
  min-width: 0;
  color: inherit;
  font: inherit;
  text-decoration: none;
}

.prayer {
  background: white;
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.prayer .label {
  font-size: .7rem;
  margin-bottom: 2px;
}

.prayer h2 {
  font-size: clamp(1rem, 1.45vw, 1.35rem);
  line-height: 1.05;
  margin-bottom: 7px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.cleanersMini {
  background: #111;
  color: #ffd700;
  border-radius: 10px;
  padding: 5px 8px;
  line-height: 1.05;
  border: 2px solid #ffd700;
}

.cleanersMini span {
  display: block;
  color: white;
  font-size: clamp(.72rem, .95vw, .9rem);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .6px;
  margin-bottom: 3px;
}

.cleanersMini strong {
  display: block;
  font-size: clamp(1rem, 1.35vw, 1.25rem);
  font-weight: 900;
  line-height: 1.05;
}

/* BIRTHDAY CORNER */
.birthdayCard {
  background: #fffdf0;
  color: #111;
  border-color: #111;
  border-left: 7px solid #ffd700;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.birthdayCard::before {
  content: "";
  display: none;
}

.birthdayCard .label {
  color: #111;
  font-size: .72rem;
  margin-bottom: 6px;
}

.birthdayCard .label {
  line-height: 1.10;
}

.birthdayList {
  height: auto;
  min-height: 0;
  display: flex;
  align-items: center;
}

.birthdayItem {
width: 100%;
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 15px;
  background: #111;
  color: white;
  border: 3px solid #ffd700;
  border-radius: 14px;
  padding: 9px 12px;
  min-height: 100px;
  overflow: hidden;
  box-shadow: inset 0 0 0 2px rgba(255,255,255,.08);
}

.birthdayIcon {
  width: 42px;
  height: 42px;
  background: #ffd700;
  color: #111;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 1.35rem;
  flex-shrink: 0;
  box-shadow: 2px 2px 0 rgba(0,0,0,.35);
}

.birthdayContent {
  min-width: 0;
}

.birthdayItem strong {
  display: block;
  color: #ffd700;
  font-size: clamp(.7rem, .96vw, 1.00rem);
  text-transform: uppercase;
  letter-spacing: .7px;
  line-height: 1;
  margin-bottom: 3px;
}

.birthdayItem h3 {
  color: white;
 font-size: clamp(.95rem, 1.2vw, 1.2rem);
  line-height: 1.00;
  font-weight: 800;
  margin-bottom: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.birthdayItem p {
  color: #f5f5f5;
  font-size: clamp(.68rem, .85vw, .82rem);
  line-height: 1.1;
  font-weight: 550;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.noBirthday {
  width: 100%;
  background: #111;
  border: 3px solid #ffd700;
  border-radius: 14px;
  padding: 10px 12px;
  text-align: center;
  font-weight: 900;
  color: white;
}

.noBirthday span {
  display: block;
  font-size: 1.45rem;
  line-height: 1;
  margin-bottom: 3px;
}

.noBirthday p {
  font-size: clamp(.72rem, .9vw, .85rem);
  line-height: 1.1;
  color: #ffd700;
}

/* MAIN GRID */
.mainGrid {
  display: grid;
  grid-template-columns: 1.1fr 1.7fr .9fr;
  grid-template-rows: 1fr 1fr;
  gap: 7px;
  min-height: 0;
}

.card h2 {
  font-size: clamp(1.05rem, 1.35vw, 1.35rem);
  margin-bottom: 6px;
  padding-bottom: 6px;
  border-bottom: 3px solid #ffd700;
  line-height: 1.1;
}

.announcementHeading {
  display: flex;
  align-items: center;
  gap: 8px;
}

.announcementHeading > #announcementTitle {
  min-width: 0;
  flex: 1;
  margin-bottom: 0;
  border-bottom: 0;
}

.announcementTimerToggle {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  padding: 0;
  border: 1px solid #111;
  border-radius: 50%;
  background: #111;
  color: #ffd700;
  font-size: .68rem;
  font-weight: 1000;
  line-height: 1;
  cursor: pointer;
}

.announcementTimerToggle.isPaused {
  background: #ffd700;
  color: #111;
}

.announcementTimerToggle:disabled {
  opacity: .38;
  cursor: default;
}

.announcementProgress {
  position: relative;
  width: 100%;
  height: 3px;
  margin-bottom: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(247, 198, 0, .22);
}

.announcementProgress > span {
  width: 0;
  height: 100%;
  display: block;
  border-radius: inherit;
  background: #ffd700;
  box-shadow: 0 0 5px rgba(247, 198, 0, .42);
}

.announcementProgress.isStatic {
  opacity: .6;
}

html.phone-device .announcementHeading {
  width: 100% !important;
  display: flex !important;
  align-items: center !important;
  gap: 8px !important;
}

html.phone-device .announcementHeading > #announcementTitle {
  min-width: 0 !important;
  flex: 1 1 auto !important;
}

html.phone-device .announcementTimerToggle {
  width: 30px !important;
  height: 30px !important;
  flex: 0 0 30px !important;
  display: grid !important;
  visibility: visible !important;
}

.scheduleCard {
  grid-row: span 2;
  overflow: hidden;
  min-height: 0;
}

.announcementsCard {
  grid-row: span 2;
  overflow: hidden;
  min-height: 0;
}

.sideCard {
  overflow: hidden;
  min-height: 0;
}

.sideCard h2 {
  font-size: clamp(1.05rem, 1.35vw, 1.25rem);
}

/* SCROLL AREAS */
#scheduleList,
#thingsList,
#reminderList {
  overflow-y: auto;
  padding-right: 6px;
}

#scheduleList {
  max-height: calc(100% - 36px);
}

#thingsList,
#reminderList {
  height: 100%;
  max-height: none;
  flex: 1;
  overflow-y: auto;
  padding-right: 6px;
}
#announcementList {
  height: calc(100% - 36px);
  overflow: hidden;
}

/* CONTENT CARDS WITH WRAPPED LEFT BORDER ACCENT */
.schedule-item,
.announcement-item,
.thing-item,
.reminder-item {
  position: relative;
  background: #fff7c7;

  border-left: 4px solid #111;
  border-top-left-radius: 17px;
  border-bottom-left-radius: 17px;
  border-top-right-radius: 15px;
  border-bottom-right-radius: 15px;

  margin-bottom: 8px;
  line-height: 1.20;
  overflow: hidden;
}

/* TODAY'S SCHEDULE */
.schedule-item {
  padding: 12px 14px 12px 18px;
  min-height: 74px;
  font-size: 1rem;
}

.schedule-item strong {
  font-size: 1rem;
  font-weight: 900;
}

.schedule-item small {
  font-size: .78rem;
  line-height: 1.2;
}

.subject-name {
  display: inline-block;
  font-size: 1.05rem;
  font-weight: 900;
  margin-top: 2px;
}

.schedule-text-link,
.schedule-text-link:visited,
.schedule-text-link:hover,
.schedule-text-link:active {
  color: inherit;
  text-decoration: none;
}

.schedule-text-link {
  cursor: pointer;
}

.schedule-text-link:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: 3px;
  border-radius: 6px;
}

.current-row {
  min-height: 82px;
  outline: 3px solid #111;
  box-shadow: 0 0 0 3px #ffd700 inset;
}

.current-badge {
  display: inline-block;
  background: #111;
  color: #ffd700;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: .65rem;
  font-weight: 900;
  margin-bottom: 4px;
}

/* THINGS TO BRING / REMINDERS */
.thing-item,
.reminder-item {
  padding: 9px 11px 9px 18px;
  font-size: clamp(.95rem, 1.15vw, 1.08rem);
}

.thing-item strong {
  font-size: clamp(1rem, 1.25vw, 1.15rem);
}

.thing-date {
  font-size: 0.72em;
  font-weight: 800;
  opacity: 0.75;
  margin-left: 4px;
  white-space: nowrap;
}

small {
  color: #444;
  font-size: clamp(.78rem, .95vw, .9rem);
  line-height: 1.2;
}

/* SUBJECT ANNOUNCEMENT */
.rotating-announcement {
  height: 100%;
}

.announcement-item {
  position: relative;
  height: 100%;
  min-height: 0;
  padding: 58px 20px 62px 24px;
  background: #fff7c7;
  border-left: 4px solid #111;
  border-radius: 17px 15px 15px 17px;
  overflow: hidden;
}

.announcement-top-left {
  position: absolute;
  top: 14px;
  left: 18px;
  right: 18px;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-start;
  align-items: center;
  gap: 7px;
  z-index: 2;
}

.announcement-subject-row {
  display: flex;
  align-items: center;
  justify-content: flex-start;
}

.announcement-subject-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  max-width: 100%;
  padding: 7px 13px;
  border-radius: 999px;
  font-size: clamp(.82rem, 1.1vw, .98rem);
  font-weight: 850;
  border: 2px solid rgba(0,0,0,.35);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  box-shadow: 2px 2px 0 rgba(0,0,0,.22);
  line-height: 1;
}

.priority-mini {
  background: #111;
  color: #ffd700;
  padding: 3px 7px;
  border-radius: 999px;
  font-size: .58em;
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: .5px;
  flex-shrink: 0;
}

.announcement-center-content {
  height: 100%;
  min-height: 95px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 12px;
  text-align: center;
}

.announcement-main-text {
  width: 100%;
  max-width: 92%;
  font-size: clamp(0.86rem, 1.67vw, 2.05rem);
  font-weight: 720;
  line-height: 1.28;
  color: #111;
  text-align: center;
  overflow-wrap: anywhere;
}

.announcement-size-md .announcement-center-content {
  gap: 9px;
}

.announcement-size-md .announcement-main-text {
  font-size: clamp(.82rem, 1.35vw, 1.55rem);
  line-height: 1.24;
  max-width: 94%;
}

.announcement-size-sm .announcement-center-content {
  gap: 7px;
}

.announcement-size-sm .announcement-main-text {
  font-size: clamp(.78rem, 1.08vw, 1.18rem);
  line-height: 1.22;
  max-width: 95%;
  font-weight: 760;
}

.announcement-size-xs .announcement-center-content {
  gap: 6px;
}

.announcement-size-xs .announcement-main-text {
  font-size: clamp(.72rem, .92vw, 1rem);
  line-height: 1.18;
  max-width: 96%;
  font-weight: 760;
}

.announcement-size-sm .formattedText,
.announcement-size-xs .formattedText {
  line-height: inherit;
}

.announcement-size-sm ul.formattedText,
.announcement-size-sm ol.formattedText,
.announcement-size-xs ul.formattedText,
.announcement-size-xs ol.formattedText {
  padding-left: 1.15em;
}

.announcement-size-sm ul.formattedText li,
.announcement-size-sm ol.formattedText li,
.announcement-size-xs ul.formattedText li,
.announcement-size-xs ol.formattedText li {
  margin-bottom: .12em;
}

.announcement-size-sm .announcement-footer,
.announcement-size-xs .announcement-footer {
  font-size: clamp(.7rem, .86vw, .9rem);
  line-height: 1.15;
}

.formattedText {
  width: 100%;
  line-height: 1.35;
  white-space: normal;
}

.formattedText.align-left {
  text-align: left;
}

.formattedText.align-center {
  text-align: center;
}

.formattedText.align-right {
  text-align: right;
}

ul.formattedText,
ol.formattedText {
  margin: 0;
  padding-left: 1.25em;
}

ul.formattedText li,
ol.formattedText li {
  margin-bottom: .25em;
}

.announcement-footer {
  width: 100%;
  max-width: 96%;
  font-size: clamp(.89rem, 4.92vw, 1.02rem);
  font-weight: 700;
  text-align: center;
  color: #111;
  opacity: .88;
  line-height: 1.35;
}

.announcement-controls {
  position: absolute;
  left: 18px;
  right: 18px;
  bottom: 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  z-index: 2;
}

.announcement-controls button,
.announcement-btn {
  background: #111;
  color: #ffd700;
  border: 2px solid #111;
  border-radius: 999px;
  padding: 7px 13px;
  font-size: clamp(.72rem, .95vw, .86rem);
  font-weight: 900;
  cursor: pointer;
  box-shadow: 2px 2px 0 rgba(0,0,0,.25);
  white-space: nowrap;
}

.announcement-posted-chip {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  max-width: 100%;
  padding: 5px 10px;
  border: 2px solid #111;
  border-radius: 999px;
  background: rgba(255, 255, 255, .86);
  color: #111;
  font-size: clamp(.68rem, .86vw, .82rem);
  font-weight: 900;
  line-height: 1;
  white-space: nowrap;
  box-shadow: 2px 2px 0 rgba(0, 0, 0, .16);
}

.announcement-controls button:hover,
.announcement-btn:hover {
  background: #ffd700;
  color: #111;
}

.prev-btn {
  margin-right: auto;
}

.next-btn {
  margin-left: auto;
}

#announcementTitle {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

/* TICKER */
.ticker {
  background: #111;
  color: #ffd700;
  padding: 6px 10px;
  border-radius: 12px;
  overflow: hidden;
  white-space: nowrap;
  border: 3px solid white;
  box-shadow: 4px 4px 0 rgba(0,0,0,.3);
}

#tickerText {
