/* BELL ALERT */
.bell-alert {
  position: fixed;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  max-width: calc(100vw - 24px);
  box-sizing: border-box;
  background: #111;
  color: #ffd700;
  border: 3px solid white;
  border-radius: 999px;
  padding: 7px 7px 7px 18px;
  font-weight: 900;
  font-size: 1.05rem;
  line-height: 1.15;
  z-index: 9999;
  box-shadow: 4px 4px 0 rgba(0,0,0,.35);
}

.bell-alert-text {
  min-width: 0;
  text-align: center;
}

.bell-alert-close {
  appearance: none;
  -webkit-appearance: none;
  flex: 0 0 27px;
  width: 27px;
  height: 27px;
  display: grid;
  place-items: center;
  border: 2px solid #ffd700;
  border-radius: 50%;
  padding: 0 0 2px;
  background: #fff;
  color: #111;
  font: 900 18px/1 Arial, sans-serif;
  cursor: pointer;
  box-shadow: none;
  -webkit-tap-highlight-color: transparent;
}

.bell-alert-close:hover,
.bell-alert-close:focus-visible {
  background: #ffd700;
  outline: none;
}

.bell-alert-close:active {
  transform: scale(.92);
}

