.prayerPlayerBox {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(circle at top left, rgba(255, 255, 255, .55), transparent 32%),
    radial-gradient(circle at bottom right, rgba(255, 215, 0, .36), transparent 34%),
    linear-gradient(135deg, #fff9d8, #ffd84d, #fff1a8);
}

.prayerPlayerBox::before {
  content: "";
  position: absolute;
  inset: -45%;
  background:
    radial-gradient(circle, rgba(255,255,255,.52) 0 2px, transparent 3px),
    radial-gradient(circle, rgba(255,215,0,.35) 0 3px, transparent 4px);
  background-size: 82px 82px, 128px 128px;
  animation: prayerGlowMove 20s linear infinite;
  opacity: .55;
  pointer-events: none;
}

.prayerPlayerBox::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 0%, rgba(255,255,255,.28) 42%, transparent 72%);
  animation: prayerLightSweep 8s ease-in-out infinite;
  pointer-events: none;
}

.prayerPlayerBox > * {
  position: relative;
  z-index: 2;
}

@keyframes prayerGlowMove {
  from { transform: translate(0, 0) rotate(0deg); }
  to { transform: translate(84px, 84px) rotate(360deg); }
}

@keyframes prayerLightSweep {
  0%, 100% { transform: translateX(-125%); opacity: 0; }
  45%, 62% { opacity: 1; }
  100% { transform: translateX(125%); opacity: 0; }
}

