}

.timeBox[role="button"]:active {
  transform: scale(.97);
}

.timeBox[role="button"]:focus-visible {
  outline: 3px solid #fff !important;
  outline-offset: 3px;
}

.accessMenuLayer[hidden] {
  display: none !important;
}

.accessMenuLayer {
  position: fixed;
  inset: 0;
  z-index: 999990;
  display: grid;
  place-items: center;
  padding: 20px;
}

.accessMenuBackdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  background: rgba(0, 0, 0, .58);
  cursor: default;
  opacity: 0;
