  gap: 10px;
  padding: 14px;
}

.accessMenuItem {
  display: grid;
  grid-template-columns: 44px minmax(0, 1fr) auto;
  align-items: center;
  gap: 12px;
  min-height: 68px;
  padding: 10px 12px;
  border: 2px solid #111;
  border-radius: 8px;
