}

.accessMenuItem:hover,
.accessMenuItem:focus-visible {
  background: #fff3ad;
  outline: none;
  transform: translate(-1px, -1px);
  box-shadow: 4px 4px 0 rgba(0, 0, 0, .24);
}

.accessMenuItem:active {
