  62% { transform: translateY(0) scale(1) rotate(0deg); }
  82% { opacity: 1; transform: translateY(0) scale(1) rotate(0deg); }
  100% { opacity: 0; transform: translateY(-24px) scale(.82) rotate(5deg); }
}

@keyframes shhhGlowBurst {
  0% { opacity: 0; transform: scale(.40); }
  20% { opacity: 1; transform: scale(1); }
  72% { opacity: .68; transform: scale(1.14); }
  100% { opacity: 0; transform: scale(1.30); }
}

@keyframes shhhEmojiWiggle {
  0%, 100% { transform: rotate(0deg) scale(1); }
  25% { transform: rotate(-8deg) scale(1.05); }
  50% { transform: rotate(6deg) scale(1.08); }
  75% { transform: rotate(-4deg) scale(1.03); }
}

@keyframes shhhTextPulse {
