@keyframes shhhBackdropFade {
  0%, 100% { opacity: 0; }
  10%, 88% { opacity: 1; }
}
@keyframes shhhGlowAura {
  0% { opacity: 0; transform: scale(.38); }
  14% { opacity: 1; transform: scale(1.02); }
  76% { opacity: .92; transform: scale(1.14); }
  100% { opacity: 0; transform: scale(1.28); }
}
@keyframes shhhRingPulse {
  0% { opacity: 0; transform: scale(.36); }
  12% { opacity: .92; }
  66% { opacity: .34; }
  100% { opacity: 0; transform: scale(1.2); }
}
@keyframes shhhPopupSlam {
  0% { opacity: 0; transform: translateY(54px) scale(.48) rotate(-8deg); }
  10% { opacity: 1; transform: translateY(-10px) scale(1.08) rotate(3deg); }
  18% { transform: translateY(4px) scale(.98) rotate(-1.8deg); }
  28% { transform: translateY(0) scale(1.02) rotate(0deg); }
  84% { opacity: 1; transform: translateY(0) scale(1) rotate(0deg); }
  100% { opacity: 0; transform: translateY(-18px) scale(.86) rotate(4deg); }
}
@keyframes shhhEmojiFloat {
  0% { transform: translateY(0) rotate(-2deg) scale(1); }
  100% { transform: translateY(-8px) rotate(2deg) scale(1.04); }
}
@keyframes shhhTextBounce {
  0%, 100% { transform: scale(1); }
  20% { transform: scale(1.05); }
  50% { transform: scale(1.08); }
  80% { transform: scale(1.02); }
}
@keyframes shhhBarDance {
  0%, 100% { transform: scaleY(.52); opacity: .72; }
  50% { transform: scaleY(1.08); opacity: 1; }
}
@keyframes shhhSparkle {
  0%,100% { opacity: 0; transform: translateY(8px) scale(.7) rotate(0deg); }
  50% { opacity: 1; transform: translateY(-6px) scale(1.08) rotate(12deg); }
}
@keyframes shhhChipFloat {
  0% { opacity: 0; transform: translateY(14px) scale(.76) rotate(-8deg); }
  18% { opacity: 1; transform: translateY(0) scale(1) rotate(-3deg); }
  100% { opacity: 1; transform: translateY(-10px) scale(1.03) rotate(3deg); }
}

