  inset: -18%;
  background:
    radial-gradient(circle at 23% 28%, rgba(255, 196, 40, .25), transparent 18%),
    radial-gradient(circle at 78% 32%, rgba(255, 158, 42, .17), transparent 22%),
    radial-gradient(circle at 52% 82%, rgba(120, 210, 120, .12), transparent 24%);
  mix-blend-mode: screen;
  filter: blur(28px);
  opacity: .85;
  animation: sfkAuroraDrift 16s ease-in-out infinite;
}

.sfkPageLockShimmer {
  position: absolute;
  inset: -35%;
  background: linear-gradient(115deg, transparent 0%, transparent 38%, rgba(255, 236, 170, .12) 48%, rgba(255, 236, 170, .28) 50%, rgba(255, 236, 170, .10) 52%, transparent 62%, transparent 100%);
  transform: translateX(-38%) rotate(3deg);
  animation: sfkShimmerSweep 7.5s ease-in-out infinite;
  opacity: .7;
  pointer-events: none;
}

.sfkPageLockDustField,
.sfkPageLockDustField::before,
.sfkPageLockDustField::after {
  content: "";
  position: absolute;
  inset: -12%;
  pointer-events: none;
  mix-blend-mode: screen;
  background-repeat: repeat;
  will-change: background-position;
}

.sfkPageLockDustField {
  opacity: .75;
  background-image:
    radial-gradient(circle, rgba(255, 236, 172, .58) 0 1.2px, transparent 3.4px),
    radial-gradient(circle, rgba(255, 192, 64, .38) 0 1.8px, transparent 5px),
    radial-gradient(circle, rgba(255, 248, 214, .44) 0 .9px, transparent 3px);
  background-size: 280px 280px;
  background-position: 0 0, 92px 56px, 173px 188px;
  animation: sfkDustLoopA 18s linear infinite;
}

.sfkPageLockDustField::before {
  opacity: .55;
  background-image:
    radial-gradient(circle, rgba(255, 218, 118, .52) 0 1.4px, transparent 4.2px),
    radial-gradient(circle, rgba(255, 255, 230, .36) 0 .8px, transparent 3px);
  background-size: 420px 420px;
  background-position: 60px 0, 240px 190px;
  animation: sfkDustLoopB 28s linear infinite;
}

.sfkPageLockDustField::after {
  opacity: .48;
  background-image:
    radial-gradient(circle, rgba(255, 208, 78, .42) 0 1px, transparent 3px),
    radial-gradient(circle, rgba(255, 238, 184, .34) 0 1.5px, transparent 4px);
  background-size: 220px 220px;
  background-position: 20px 80px, 130px 12px;
  animation: sfkDustLoopC 13s linear infinite reverse;
}

.sfkPageLockParticles,
.sfkPageLockLeaves {
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}

.sfkParticle {
  position: absolute;
  bottom: -7vh;
  width: var(--s, 9px);
  height: var(--s, 9px);
  border-radius: 999px;
  background: radial-gradient(circle, rgba(255,238,177,.98) 0%, rgba(255,206,72,.78) 36%, rgba(255,206,72,.20) 64%, rgba(255,206,72,0) 82%);
