.sfkPageLockCard {
  position: relative;
  z-index: 1;
  width: min(96vw, 1120px);
  max-height: calc(100dvh - 16px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  gap: clamp(8px, 1.3vh, 14px);
  align-items: center;
}

.sfkPageLockTopline {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  justify-self: center;
  padding: 10px 16px;
  border: 2px solid rgba(255,255,255,.16);
  border-radius: 999px;
  background: rgba(17, 17, 15, .72);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  box-shadow: 0 12px 30px rgba(0,0,0,.32), 0 0 36px rgba(255,205,68,.10);
}

.sfkPageLockIcon {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 2px solid rgba(255, 215, 0, .58);
  border-radius: 14px;
  background: #111;
  color: #ffd700;
  font-size: 1.2rem;
  box-shadow: 0 0 0 1px rgba(255,255,255,.06), 0 0 20px rgba(255,215,0,.16);
  flex: 0 0 auto;
  animation: sfkLockPulse 3.1s ease-in-out infinite;
}

.sfkPageLockEyebrow {
  margin: 0;
  color: #f7e6ad;
  font-size: .82rem;
  font-weight: 950;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.sfkPageLockHeroStage {
  position: relative;
  min-height: 0;
  width: 100%;
  display: grid;
  place-items: center;
  padding: clamp(8px, 1.2vh, 14px);
  border: 1px solid rgba(255,255,255,.16);
  border-radius: 30px;
  background: rgba(0, 0, 0, .18);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 24px 70px rgba(0, 0, 0, .46), 0 0 52px rgba(255, 199, 46, .12);
  overflow: hidden;
}

.sfkPageLockHeroStage.is-missing {
  display: none;
}

.sfkPageLockHeroGlow {
  position: absolute;
  inset: 4%;
  border-radius: 28px;
  background: radial-gradient(circle at 50% 32%, rgba(255, 203, 70, .20), transparent 55%);
  filter: blur(18px);
  animation: sfkHeroGlow 4.8s ease-in-out infinite;
  pointer-events: none;
}

.sfkPageLockHero {
  position: relative;
  z-index: 1;
  display: block;
  width: auto;
  max-width: 100%;
  height: auto;
  max-height: min(62vh, 64dvh, 700px);
  object-fit: contain;
  object-position: center center;
  border-radius: 20px;
  box-shadow: 0 18px 44px rgba(0, 0, 0, .46);
  background: rgba(0,0,0,.08);
}

.sfkPageLockMessagePanel {
  width: min(100%, 920px);
  justify-self: center;
  display: grid;
  gap: 6px;
  justify-items: center;
  padding: clamp(12px, 1.7vh, 18px) clamp(14px, 2vw, 24px);
  border: 2px solid rgba(255,255,255,.14);
  border-radius: 26px;
  background: rgba(8, 8, 8, .76);
  backdrop-filter: blur(13px);
  -webkit-backdrop-filter: blur(13px);
  color: #fff;
  box-shadow: 0 16px 34px rgba(0,0,0,.36), 0 0 44px rgba(255, 210, 74, .08);
  text-align: center;
}

.sfkPageLockCard h1 {
  margin: 0;
  color: #fff;
  font-size: clamp(2rem, 4.1vw, 4rem);
  font-weight: 1000;
  letter-spacing: -.05em;
  line-height: .92;
  text-transform: uppercase;
  text-shadow: 0 6px 18px rgba(0,0,0,.36), 0 0 28px rgba(255,225,130,.10);
}

.sfkPageLockMessage {
  margin: 0;
  color: #fff;
  font-size: clamp(1rem, 1.9vw, 1.3rem);
  font-weight: 950;
  line-height: 1.18;
  text-wrap: balance;
}

.sfkPageLockSubtext {
  margin: 0;
  color: rgba(255,255,255,.86);
  font-size: clamp(.82rem, 1.3vw, .96rem);
  font-weight: 800;
}

@keyframes sfkBackdropFloat {
  0%, 100% { transform: scale(1.12) translate3d(-1.4%, -1.1%, 0); }
  50% { transform: scale(1.16) translate3d(1.4%, 1.1%, 0); }
}

@keyframes sfkAuroraDrift {
  0%, 100% { transform: translate3d(-2%, -1%, 0) rotate(-2deg); opacity: .72; }
  50% { transform: translate3d(2%, 1%, 0) rotate(2deg); opacity: .98; }
}

@keyframes sfkDustLoopA {
  0% { background-position: 0 0, 92px 56px, 173px 188px; }
  100% { background-position: 0 -280px, 92px -224px, 173px -92px; }
}

@keyframes sfkDustLoopB {
  0% { background-position: 60px 0, 240px 190px; }
  100% { background-position: 60px -420px, 240px -230px; }
}

@keyframes sfkDustLoopC {
  0% { background-position: 20px 80px, 130px 12px; }
  100% { background-position: 20px -140px, 130px -208px; }
}

@keyframes sfkShimmerSweep {
  0%, 24% { transform: translateX(-58%) rotate(3deg); opacity: 0; }
  40% { opacity: .72; }
  64% { opacity: .30; }
  86%, 100% { transform: translateX(58%) rotate(3deg); opacity: 0; }
}

@keyframes sfkParticleRise {
  0% { transform: translate3d(0, 10vh, 0) scale(.55); opacity: 0; }
  8% { opacity: .72; }
  48% { transform: translate3d(calc(var(--x, 30px) * .48), -45vh, 0) scale(.96); opacity: .64; }
  88% { opacity: .46; }
  100% { transform: translate3d(var(--x, 30px), -125vh, 0) scale(1.22); opacity: 0; }
}

@keyframes sfkLeafDrift {
  0% { transform: translate3d(0, -16vh, 0) rotate(0deg); opacity: 0; }
  10% { opacity: var(--leaf-opacity, .38); }
  50% { transform: translate3d(calc(var(--leaf-x, 90px) * .45), 48vh, 0) rotate(160deg); opacity: var(--leaf-opacity, .36); }
  90% { opacity: var(--leaf-opacity, .28); }
  100% { transform: translate3d(var(--leaf-x, 90px), 126vh, 0) rotate(340deg); opacity: 0; }
}

@keyframes sfkHeroGlow {
  0%, 100% { opacity: .45; transform: scale(.98); }
  50% { opacity: .85; transform: scale(1.04); }
}

@keyframes sfkLockPulse {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 1px rgba(255,255,255,.06), 0 0 20px rgba(255,215,0,.16); }
  50% { transform: scale(1.05); box-shadow: 0 0 0 1px rgba(255,255,255,.08), 0 0 30px rgba(255,215,0,.34); }
}

@media (max-width: 900px) {
  .sfkPageLockCard {
    width: min(97vw, 760px);
  }

  .sfkPageLockHero {
    max-height: min(54vh, 58dvh, 520px);
  }

  .sfkPageLockCard h1 {
    font-size: clamp(1.7rem, 6vw, 2.9rem);
  }

  .sfkPageLockMessage {
    font-size: clamp(.96rem, 2.8vw, 1.08rem);
  }
}

@media (max-width: 700px) {
  .sfkPageLockScreen {
    padding: 8px;
  }

  .sfkPageLockCard {
    width: min(100vw - 10px, 720px);
    max-height: calc(100dvh - 10px);
    gap: 8px;
  }

  .sfkPageLockTopline {
    gap: 8px;
    padding: 8px 12px;
  }

  .sfkPageLockIcon {
    width: 36px;
    height: 36px;
    border-radius: 12px;
    font-size: 1.05rem;
  }

  .sfkPageLockEyebrow {
    font-size: .72rem;
    letter-spacing: .1em;
  }

  .sfkPageLockHeroStage {
    padding: 7px;
    border-radius: 20px;
  }

  .sfkPageLockHero {
    max-height: min(46vh, 48dvh, 330px);
    border-radius: 14px;
  }

  .sfkPageLockMessagePanel {
    gap: 5px;
    padding: 10px 12px 12px;
    border-radius: 18px;
  }

  .sfkPageLockCard h1 {
    font-size: clamp(1.42rem, 8vw, 2.2rem);
  }

  .sfkPageLockMessage {
    font-size: clamp(.9rem, 3.6vw, .98rem);
  }

  .sfkPageLockSubtext {
    font-size: .76rem;
  }
}

@media (max-height: 720px) {
  .sfkPageLockCard {
    gap: 7px;
  }

  .sfkPageLockHero {
    max-height: min(40vh, 42dvh, 280px);
  }

  .sfkPageLockMessagePanel {
    padding: 8px 12px 10px;
    gap: 4px;
  }

  .sfkPageLockCard h1 {
    font-size: clamp(1.3rem, 5.5vw, 2rem);
  }

  .sfkPageLockMessage {
    font-size: clamp(.86rem, 2vw, .94rem);
  }

  .sfkPageLockSubtext {
    font-size: .72rem;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sfkPageLockBackdropImage,
  .sfkPageLockAurora,
  .sfkPageLockShimmer,
  .sfkPageLockDustField,
  .sfkPageLockDustField::before,
  .sfkPageLockDustField::after,
  .sfkParticle,
  .sfkLeaf,
  .sfkPageLockHeroGlow,
  .sfkPageLockIcon {
    animation: none !important;
  }
}


