/* =========================================================
   v381 HOMEPAGE LIVE DISPLAY / EFFECTS
   Full-screen Admin-controlled visual layer. Weather/multiverse
   remains click-through except the X; picture/alert can act as
   a full-screen notice until dismissed when Admin allows it.
========================================================= */
.homepageEffectLayer {
  position: fixed;
  inset: 0;
  z-index: 2147482500;
  overflow: hidden;
  pointer-events: none;
  isolation: isolate;
  font-family: Arial, Helvetica, sans-serif;
}

.homepageEffectLayer[hidden] {
  display: none !important;
}

.homepageEffectBackdrop,
.homepageEffectRain,
.homepageEffectFlood,
.homepageEffectMist,
.homepageEffectLightning,
.homepageEffectMultiverse,
.homepageEffectContent {
  position: absolute;
  inset: 0;
}

.homepageEffectBackdrop {
  z-index: 0;
  background: transparent;
  transition: background .2s ease;
}

.homepageEffectClose {
  position: absolute;
  z-index: 20;
  top: max(12px, env(safe-area-inset-top));
  right: max(14px, env(safe-area-inset-right));
  width: 42px;
  height: 42px;
  min-width: 42px;
  min-height: 42px;
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #fff;
  box-shadow: none;
  text-shadow: 0 2px 8px rgba(0,0,0,.72);
  font: 400 39px/1 Arial, sans-serif;
  cursor: pointer;
  pointer-events: auto;
  -webkit-tap-highlight-color: transparent;
}

.homepageEffectClose:hover,
.homepageEffectClose:focus-visible {
  background: transparent;
  color: #fff;
  outline: 2px solid rgba(255,255,255,.9);
  outline-offset: 1px;
}

.homepageEffectRain {
  z-index: 3;
  overflow: hidden;
  transform: skewX(-7deg);
}

.homepageEffectRain i {
  position: absolute;
  left: var(--rain-left);
  top: -15vh;
  width: 1.2px;
  height: var(--rain-length);
  opacity: var(--rain-opacity);
  border-radius: 999px;
  background: linear-gradient(to bottom, rgba(255,255,255,0), rgba(220,239,255,.98));
  box-shadow: 0 0 2px rgba(190,226,255,.45);
  animation: sfkHomepageRainFall var(--rain-duration) linear var(--rain-delay) infinite;
  will-change: transform;
}

@keyframes sfkHomepageRainFall {
  from { transform: translate3d(0, -12vh, 0); }
  to { transform: translate3d(-15vw, 135vh, 0); }
}

.homepageEffectLayer.is-drizzle .homepageEffectBackdrop {
  background: linear-gradient(180deg, rgba(68,91,111,.13), rgba(44,65,85,.06));
}

.homepageEffectLayer.is-heavy-rain .homepageEffectBackdrop,
.homepageEffectLayer.is-thunderstorm .homepageEffectBackdrop,
.homepageEffectLayer.is-flood-rain .homepageEffectBackdrop {
  background:
    radial-gradient(circle at 18% 10%, rgba(255,255,255,.06), transparent 26%),
    radial-gradient(circle at 76% 14%, rgba(255,255,255,.04), transparent 24%),
    linear-gradient(180deg, rgba(9,18,31,.56), rgba(19,32,46,.40));
  backdrop-filter: saturate(.72) brightness(.74);
}

.homepageEffectMist {
  z-index: 2;
  opacity: 0;
  background:
    radial-gradient(circle at 18% 14%, rgba(219,232,242,.24), transparent 34%),
    radial-gradient(circle at 72% 18%, rgba(219,232,242,.20), transparent 38%),
    radial-gradient(circle at 54% 38%, rgba(164,188,204,.16), transparent 42%),
    linear-gradient(180deg, rgba(16,22,31,.16), rgba(32,44,55,.08));
  animation: sfkHomepageMist 7s ease-in-out infinite alternate;
}

.homepageEffectLayer.is-heavy-rain .homepageEffectMist,
.homepageEffectLayer.is-thunderstorm .homepageEffectMist,
.homepageEffectLayer.is-flood-rain .homepageEffectMist {
  opacity: 1;
}

@keyframes sfkHomepageMist {
  from { transform: translate3d(-2%, 0, 0) scale(1.03); }
  to { transform: translate3d(2%, 1%, 0) scale(1.08); }
}

.homepageEffectLightning {
  z-index: 5;
  opacity: 0;
  background: rgba(226,239,255,.9);
  mix-blend-mode: screen;
  pointer-events: none;
}

.homepageEffectLayer.is-thunderstorm .homepageEffectLightning {
  animation: sfkHomepageLightning 7.4s steps(1, end) infinite;
}

@keyframes sfkHomepageLightning {
  0%, 72%, 75%, 78%, 100% { opacity: 0; }
  73% { opacity: .72; }
  74% { opacity: .08; }
  76% { opacity: .46; }
  77% { opacity: .12; }
}

.homepageEffectContent {
  z-index: 10;
  display: grid;
  place-items: center;
  padding: max(22px, env(safe-area-inset-top)) max(22px, env(safe-area-inset-right)) max(22px, env(safe-area-inset-bottom)) max(22px, env(safe-area-inset-left));
