/* =========================================================
   v385 HOMEPAGE EFFECTS PACK
   Stronger multiverse/glitch + additional Admin modes.
   All decorative layers remain click-through; only the X is interactive.
========================================================= */
.homepageEffectParticles {
  position: absolute;
  inset: 0;
  z-index: 4;
  display: none;
  overflow: hidden;
  pointer-events: none;
  contain: layout paint style;
}

.homepageEffectLayer.is-fog .homepageEffectParticles,
.homepageEffectLayer.is-snow .homepageEffectParticles,
.homepageEffectLayer.is-confetti .homepageEffectParticles,
.homepageEffectLayer.is-hearts .homepageEffectParticles,
.homepageEffectLayer.is-stars .homepageEffectParticles,
.homepageEffectLayer.is-matrix .homepageEffectParticles,
.homepageEffectLayer.is-bubbles .homepageEffectParticles,
.homepageEffectLayer.is-fireflies .homepageEffectParticles,
.homepageEffectLayer.is-minions .homepageEffectParticles,
.homepageEffectLayer.is-spongebob .homepageEffectParticles,
.homepageEffectLayer.is-naruto .homepageEffectParticles,
.homepageEffectLayer.is-akatsuki .homepageEffectParticles,
.homepageEffectLayer.is-ninja-night .homepageEffectParticles,
.homepageEffectLayer.is-neon-pulse .homepageEffectParticles {
  display: block;
}

.homepageAmbientParticle {
  position: absolute;
  left: var(--fx-x);
  top: var(--fx-y);
  pointer-events: none;
  opacity: var(--fx-alpha, .7);
  will-change: transform, opacity;
}

/* ---------- Strong Multiverse / Dimensional Glitch ---------- */
html.sfkHomepageMultiverseActive body > *:not(script):not(style):not(#homepageEffectLayer) {
  animation: sfkUnderlyingGlitch 1.35s steps(1, end) infinite;
  transform-origin: center center;
  will-change: transform, filter;
}

.homepageEffectLayer.is-multiverse .homepageEffectBackdrop {
  background:
    linear-gradient(90deg, rgba(0,224,255,.13), transparent 22%, transparent 76%, rgba(255,0,106,.15)),
    rgba(12, 2, 26, .18);
  backdrop-filter: saturate(1.55) contrast(1.16) hue-rotate(8deg);
  box-shadow:
    inset 20px 0 0 rgba(0,225,255,.16),
    inset -20px 0 0 rgba(255,0,102,.17),
    inset 0 0 80px rgba(113,0,255,.16);
  animation: sfkMultiverseBackdropHit 1.55s steps(1, end) infinite;
}

.homepageEffectLayer.is-multiverse .homepageEffectMultiverse {
  display: block;
  opacity: 1;
  mix-blend-mode: screen;
  background:
    repeating-linear-gradient(0deg, rgba(255,255,255,.09) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, transparent 0 12vw, rgba(0,235,255,.12) 12vw 12.5vw, transparent 12.5vw 24vw),
    radial-gradient(circle at 18% 26%, rgba(0,229,255,.42), transparent 26%),
    radial-gradient(circle at 82% 68%, rgba(255,0,119,.4), transparent 30%),
    radial-gradient(circle at 52% 44%, rgba(125,0,255,.24), transparent 34%);
  animation: sfkMultiverseHardScreen 1.7s steps(2, end) infinite;
}

.homepageEffectLayer.is-multiverse .homepageEffectMultiverse span {
  width: 58vw;
  height: 24vh;
  border: 3px solid rgba(255,255,255,.52);
  background: linear-gradient(90deg, rgba(0,229,255,.30), rgba(120,0,255,.16) 48%, rgba(255,0,106,.28));
  box-shadow: 12px 0 0 rgba(255,0,110,.15), -12px 0 0 rgba(0,226,255,.15);
  filter: saturate(1.8) contrast(1.2);
  opacity: .72;
  animation-duration: 1.9s;
}

.homepageEffectLayer.is-multiverse::before,
.homepageEffectLayer.is-multiverse::after {
  opacity: .58;
  mix-blend-mode: screen;
}

.homepageEffectLayer.is-multiverse::before {
  background:
    repeating-linear-gradient(0deg, transparent 0 8vh, rgba(0,235,255,.62) 8vh 9.2vh, transparent 9.2vh 18vh),
    repeating-linear-gradient(90deg, transparent 0 13vw, rgba(0,229,255,.35) 13vw 13.5vw, transparent 13.5vw 27vw);
  animation: sfkMultiverseSliceCyan .92s steps(2, end) infinite;
}

.homepageEffectLayer.is-multiverse::after {
  background:
    repeating-linear-gradient(0deg, transparent 0 10vh, rgba(255,0,106,.58) 10vh 11.1vh, transparent 11.1vh 22vh),
    repeating-linear-gradient(90deg, transparent 0 18vw, rgba(255,0,106,.34) 18vw 18.6vw, transparent 18.6vw 33vw);
  animation: sfkMultiverseSliceMagenta 1.08s steps(2, end) infinite reverse;
}

@keyframes sfkUnderlyingGlitch {
  0%, 7%, 15%, 48%, 54%, 82%, 100% { transform: translate3d(0,0,0); filter: none; }
  8% { transform: translate3d(5px,-1px,0) skewX(.35deg); filter: saturate(1.4) contrast(1.12) hue-rotate(8deg); }
  9% { transform: translate3d(-6px,1px,0) skewX(-.5deg); filter: saturate(1.7) hue-rotate(-13deg); }
  10% { transform: translate3d(2px,0,0); }
  49% { transform: translate3d(-4px,2px,0); filter: contrast(1.2) saturate(1.5); }
  50% { transform: translate3d(7px,-1px,0); filter: hue-rotate(18deg) saturate(1.8); }
  51% { transform: translate3d(-2px,0,0); }
  83% { transform: translate3d(4px,0,0) skewY(.25deg); filter: hue-rotate(-16deg) contrast(1.18); }
  84% { transform: translate3d(-5px,-1px,0); }
}

@keyframes sfkMultiverseBackdropHit {
  0%, 12%, 18%, 58%, 65%, 100% { opacity: 1; }
  13% { opacity: .65; filter: hue-rotate(35deg); }
  14% { opacity: 1; }
  59% { opacity: .72; }
  60% { opacity: 1; }
}

@keyframes sfkMultiverseHardScreen {
  0%, 100% { transform: translate3d(0,0,0) scale(1); filter: hue-rotate(0deg); }
  10% { transform: translate3d(7px,-2px,0) scale(1.006); filter: hue-rotate(32deg); }
  12% { transform: translate3d(-9px,2px,0) scale(1.01); }
  14% { transform: translate3d(0,0,0) scale(1); }
  43% { transform: translate3d(-5px,0,0); filter: hue-rotate(-28deg); }
  45% { transform: translate3d(8px,1px,0); }
  47% { transform: translate3d(0,0,0); }
  74% { transform: translate3d(4px,-1px,0); filter: hue-rotate(24deg); }
  77% { transform: translate3d(-6px,1px,0); }
}

@keyframes sfkMultiverseSliceCyan {
  0%,100% { clip-path: inset(0 0 78% 0); transform: translateX(-11px); }
  25% { clip-path: inset(24% 0 57% 0); transform: translateX(9px); }
  51% { clip-path: inset(49% 0 32% 0); transform: translateX(-7px); }
