/* ---------- Spider-Verse inspired RGB glitch (original treatment; no logos/characters) ---------- */
html.sfkHomepageSpiderGlitchActive body > *:not(script):not(style):not(#homepageEffectLayer) {
  animation: sfkSpiderUnderlyingGlitch .86s steps(1, end) infinite;
  transform-origin: center;
  will-change: transform, filter;
}
.homepageEffectLayer.is-spider-glitch .homepageEffectBackdrop {
  background:
    radial-gradient(circle at 48% 44%, rgba(255,255,255,.03), transparent 28%),
    repeating-radial-gradient(circle at 50% 50%, transparent 0 14px, rgba(238,20,50,.08) 15px 16px, transparent 17px 30px),
    repeating-conic-gradient(from 0deg at 50% 50%, rgba(0,196,255,.07) 0 1deg, transparent 1deg 14deg),
    rgba(0,0,4,.62);
  backdrop-filter: contrast(1.38) saturate(1.72) brightness(.76);
  box-shadow: inset 24px 0 0 rgba(0,225,255,.13), inset -24px 0 0 rgba(255,20,55,.18);
}
.homepageEffectLayer.is-spider-glitch .homepageEffectMultiverse {
  display: block;
  opacity: 1;
  background:
    repeating-linear-gradient(0deg, rgba(255,255,255,.10) 0 1px, transparent 1px 4px),
    repeating-linear-gradient(90deg, transparent 0 8vw, rgba(0,232,255,.13) 8vw 8.4vw, transparent 8.4vw 16vw),
    radial-gradient(circle at 42% 48%, rgba(237,12,46,.18), transparent 32%),
    rgba(0,0,0,.12);
  mix-blend-mode: screen;
  animation: sfkSpiderGlitchLayer .74s steps(2,end) infinite;
}
.homepageEffectLayer.is-spider-glitch .homepageEffectMultiverse span {
  width: 72vw;
  height: 11vh;
  border: 0;
  border-left: 8px solid rgba(0,232,255,.8);
  border-right: 8px solid rgba(255,22,54,.82);
  border-radius: 0;
  background: linear-gradient(90deg, rgba(0,230,255,.40), rgba(255,255,255,.05) 42%, rgba(255,15,55,.44));
  box-shadow: -14px 0 0 rgba(0,72,255,.34), 14px 0 0 rgba(255,0,121,.30);
  clip-path: polygon(0 18%, 100% 0, 98% 75%, 2% 100%);
  opacity: .88;
  animation: sfkSpiderSlice .9s steps(2,end) infinite alternate;
}
.homepageEffectLayer.is-spider-glitch::before,
.homepageEffectLayer.is-spider-glitch::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 7;
  pointer-events: none;
  mix-blend-mode: screen;
}
.homepageEffectLayer.is-spider-glitch::before {
  background:
    repeating-linear-gradient(0deg, transparent 0 7vh, rgba(0,235,255,.78) 7vh 8vh, transparent 8vh 14vh),
    repeating-linear-gradient(90deg, transparent 0 19vw, rgba(0,105,255,.34) 19vw 19.7vw, transparent 19.7vw 34vw);
  opacity: .62;
  animation: sfkSpiderCyanCut .68s steps(2,end) infinite;
}
.homepageEffectLayer.is-spider-glitch::after {
  background:
    repeating-linear-gradient(0deg, transparent 0 9vh, rgba(255,18,53,.76) 9vh 10vh, transparent 10vh 18vh),
    radial-gradient(circle at 50% 48%, transparent 0 13%, rgba(255,0,95,.12) 14% 15%, transparent 16% 26%, rgba(0,225,255,.12) 27% 28%, transparent 29%);
  opacity: .62;
  animation: sfkSpiderRedCut .79s steps(2,end) infinite reverse;
}
.homepageAmbientParticle.is-spider-glitch {
  width: clamp(8px, var(--fx-size), 34px);
  height: clamp(2px, calc(var(--fx-size) * .22), 7px);
  background: hsl(var(--fx-hue) 100% 58%);
  box-shadow: 7px 0 0 rgba(0,230,255,.7), -7px 0 0 rgba(255,16,52,.72);
  animation: sfkSpiderBits var(--fx-duration) steps(3,end) var(--fx-delay) infinite;
}
@keyframes sfkSpiderUnderlyingGlitch {
  0%,8%,18%,41%,51%,72%,100% { transform: translate3d(0,0,0); filter: none; }
  9% { transform: translate3d(9px,-1px,0) skewX(.6deg); filter: contrast(1.25) saturate(1.8) hue-rotate(18deg); }
  10% { transform: translate3d(-11px,1px,0) skewX(-.7deg); filter: contrast(1.35) saturate(1.9) hue-rotate(-22deg); }
  42% { transform: translate3d(-7px,2px,0); filter: hue-rotate(-35deg) saturate(2); }
  43% { transform: translate3d(10px,-2px,0); }
  73% { transform: translate3d(5px,1px,0) skewY(.4deg); filter: contrast(1.3) hue-rotate(28deg); }
  74% { transform: translate3d(-6px,-1px,0); }
}
@keyframes sfkSpiderGlitchLayer {
  0%,100% { transform: translateX(0); filter: hue-rotate(0); }
  20% { transform: translateX(10px); filter: hue-rotate(35deg); }
  23% { transform: translateX(-12px); }
  47% { transform: translateX(-7px); filter: hue-rotate(-42deg); }
  51% { transform: translateX(8px); }
}
@keyframes sfkSpiderSlice { from { transform: translateX(-22px) scaleX(.98); } to { transform: translateX(28px) scaleX(1.03); } }
@keyframes sfkSpiderCyanCut {
  0%,100% { clip-path: inset(1% 0 83% 0); transform: translateX(-17px); }
  32% { clip-path: inset(31% 0 48% 0); transform: translateX(14px); }
  65% { clip-path: inset(62% 0 17% 0); transform: translateX(-12px); }
}
@keyframes sfkSpiderRedCut {
  0%,100% { clip-path: inset(13% 0 66% 0); transform: translateX(16px); }
  35% { clip-path: inset(44% 0 37% 0); transform: translateX(-15px); }
  70% { clip-path: inset(76% 0 5% 0); transform: translateX(12px); }
}
@keyframes sfkSpiderBits {
  0%,100% { transform: translate3d(-10px,0,0); opacity: .15; }
  32% { transform: translate3d(30px,-3px,0); opacity: .92; }
  60% { transform: translate3d(-20px,4px,0); opacity: .35; }
}

