  17% { opacity:1; transform:translate(-18vw,-39vh) scale(.86) rotate(-5deg); }
  27% { opacity:1; transform:translate(34vw,-36vh) scale(.90) rotate(9deg); }
  37% { opacity:1; transform:translate(49vw,-12vh) scale(.92) rotate(18deg); }
  47% { opacity:1; transform:translate(46vw,24vh) scale(.90) rotate(14deg); }
  57% { opacity:1; transform:translate(8vw,35vh) scale(.88) rotate(3deg); }
  67% { opacity:1; transform:translate(-42vw,30vh) scale(.86) rotate(-10deg); }
  77% { opacity:1; transform:translate(-52vw,4vh) scale(.88) rotate(-18deg); }
  87% { opacity:1; transform:translate(-38vw,-24vh) scale(.86) rotate(-12deg); }
  94% { opacity:.96; transform:translate(20vw,-31vh) scale(.88) rotate(5deg); }
  100% { opacity:0; transform:translate(116vw,-18vh) scale(.66) rotate(14deg); }
}
@keyframes sfkSpiderWebBuild {
  0%, 5% {
    opacity: 0;
    transform: rotate(var(--web-rot)) scale(.10);
    clip-path: circle(0% at var(--web-origin));
    filter: drop-shadow(0 0 2px rgba(255,255,255,.05));
  }
  14% {
    opacity: .48;
    transform: rotate(var(--web-rot)) scale(.62);
    clip-path: circle(34% at var(--web-origin));
  }
  24% {
    opacity: .66;
    transform: rotate(var(--web-rot)) scale(.82);
    clip-path: circle(70% at var(--web-origin));
  }
  34% {
    opacity: .78;
    transform: rotate(var(--web-rot)) scale(.96);
    clip-path: circle(112% at var(--web-origin));
  }
  42%, 82% {
    opacity: .86;
    transform: rotate(var(--web-rot)) scale(1);
    clip-path: circle(150% at var(--web-origin));
    filter: drop-shadow(0 0 9px rgba(255,255,255,.32));
  }
  58% {
    opacity: .72;
    transform: rotate(var(--web-rot)) scale(1.015);
    clip-path: circle(150% at var(--web-origin));
    filter: drop-shadow(0 0 6px rgba(255,255,255,.22));
  }
  74% {
    opacity: .88;
    transform: rotate(var(--web-rot)) scale(1);
    clip-path: circle(150% at var(--web-origin));
    filter: drop-shadow(0 0 10px rgba(255,255,255,.32));
  }
  90% {
    opacity: .64;
    transform: rotate(var(--web-rot)) scale(.98);
    clip-path: circle(150% at var(--web-origin));
  }
  100% {
    opacity: 0;
    transform: rotate(var(--web-rot)) scale(.72);
    clip-path: circle(150% at var(--web-origin));
  }
}
@keyframes sfkSpiderThreadBuild {
  0%, 8% {
    opacity: 0;
    transform: rotate(var(--thread-rot)) scaleY(0);
  }
  20% {
    opacity: .42;
    transform: rotate(var(--thread-rot)) scaleY(.36);
  }
  34% {
    opacity: .58;
    transform: rotate(var(--thread-rot)) scaleY(.78);
  }
  44%, 74% {
    opacity: .62;
    transform: rotate(var(--thread-rot)) scaleY(1);
  }
  58% {
    opacity: .34;
    transform: rotate(calc(var(--thread-rot) - 4deg)) translateX(-6px) scaleY(1);
  }
  70% {
    opacity: .6;
    transform: rotate(calc(var(--thread-rot) + 4deg)) translateX(8px) scaleY(1);
  }
  86% {
    opacity: .42;
    transform: rotate(var(--thread-rot)) scaleY(.92);
  }
  100% {
    opacity: 0;
    transform: rotate(var(--thread-rot)) scaleY(0);
  }
}

