/* Rain + rising flood water. */
.homepageEffectFlood {
  z-index: 4;
  display: none;
  top: auto !important;
  bottom: -4vh !important;
  height: 14vh;
  overflow: visible;
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(174,230,255,.12) 0%, rgba(73,157,199,.34) 9%, rgba(17,75,112,.84) 36%, rgba(5,37,63,.96) 100%);
  box-shadow: 0 -18px 46px rgba(76,177,225,.30), inset 0 15px 25px rgba(255,255,255,.11), inset 0 -16px 32px rgba(0,0,0,.26);
  animation: sfkFloodLevel 34s cubic-bezier(.42,0,.34,1) infinite;
  will-change: height, transform, filter;
}

.homepageEffectLayer.is-flood-rain .homepageEffectFlood { display: block; }
.homepageEffectLayer.is-flood-rain .homepageEffectBackdrop {
  background:
    radial-gradient(circle at 50% -8%, rgba(173,186,198,.15), transparent 28%),
    radial-gradient(circle at 24% 8%, rgba(255,255,255,.05), transparent 16%),
    radial-gradient(circle at 78% 10%, rgba(255,255,255,.04), transparent 18%),
    linear-gradient(180deg, rgba(5,10,18,.76) 0%, rgba(14,21,31,.60) 34%, rgba(18,27,38,.48) 100%);
  backdrop-filter: saturate(.56) brightness(.50) blur(1.15px);
  animation: sfkFloodStormDarkness 34s ease-in-out infinite;
}
.homepageEffectLayer.is-flood-rain .homepageEffectRain { opacity: 1; }
.homepageEffectLayer.is-flood-rain .homepageEffectRain i {
  width: 2.35px;
  min-height: 62px;
  background: linear-gradient(to bottom, rgba(255,255,255,0), rgba(246,252,255,1));
  box-shadow: 0 0 7px rgba(214,236,255,.78);
  filter: brightness(1.22);
  opacity: .96;
}
.homepageEffectLayer.is-flood-rain .homepageEffectMist { opacity: 1; }

.homepageFloodWave {
  position: absolute;
  left: -18%;
  width: 136%;
  height: 68px;
  top: -34px;
  border-radius: 46%;
  background:
    radial-gradient(ellipse at 20px 28px, rgba(233,249,255,.68) 0 10px, transparent 11px) 0 0 / 56px 42px repeat-x,
    radial-gradient(ellipse at 34px 37px, rgba(74,178,219,.95) 0 22px, transparent 23px) 0 6px / 76px 46px repeat-x,
    linear-gradient(180deg, rgba(168,229,255,.14), rgba(0,0,0,0));
  filter: drop-shadow(0 6px 8px rgba(0,56,91,.34));
}
.homepageFloodWave.is-back { opacity:.72; animation: sfkFloodWaveBack 4.2s linear infinite; }
.homepageFloodWave.is-front { top:-20px; opacity:.98; transform: scaleY(.92); animation: sfkFloodWaveFront 2.6s linear infinite reverse; }
.homepageFloodShine {
  position:absolute;
  inset: 6% 0 0;
  background:
    repeating-linear-gradient(103deg, transparent 0 8vw, rgba(255,255,255,.13) 8.5vw 10vw, transparent 10.5vw 19vw),
    repeating-radial-gradient(ellipse at 50% 0%, rgba(255,255,255,.16) 0 1px, transparent 2px 22px);
  opacity:.88;
  animation: sfkFloodShimmer 4.3s ease-in-out infinite alternate;
}
@keyframes sfkFloodLevel {
  0%, 7% { height: 12vh; transform: translateY(3vh); filter: brightness(.96); }
  22% { height: 28vh; transform: translateY(2vh); filter: brightness(.94); }
  42% { height: 58vh; transform: translateY(1vh); filter: brightness(.90); }
  62% { height: 88vh; transform: translateY(0); filter: brightness(.86); }
  72%, 79% { height: 112vh; transform: translateY(0); filter: brightness(.80); }
  90% { height: 52vh; transform: translateY(1vh); filter: brightness(.90); }
  100% { height: 12vh; transform: translateY(3vh); filter: brightness(.96); }
}
@keyframes sfkFloodStormDarkness {
  0%,100% { filter: brightness(.98); opacity:.94; }
  48% { filter: brightness(.86); opacity:1; }
  72%,79% { filter: brightness(.70); opacity:1; }
}
@keyframes sfkFloodWaveBack { from { transform:translateX(-54px) scaleY(.92); } to { transform:translateX(54px) scaleY(1.08); } }
@keyframes sfkFloodWaveFront { from { transform:translateX(-46px) scaleY(.82); } to { transform:translateX(46px) scaleY(1); } }
@keyframes sfkFloodShimmer { from { transform:translateX(-4%); opacity:.52; } to { transform:translateX(4%); opacity:.96; } }

@media (max-width:700px) {
  .homepageEffectFlood { animation-duration: 36s; }
}

@media (prefers-reduced-motion: reduce) {
  html.sfkHomepageBlackSymbioteActive body > *:not(script):not(style):not(#homepageEffectLayer),
  .homepageEffectLayer.is-black-symbiote .homepageEffectMultiverse,
  .homepageEffectLayer.is-black-symbiote .homepageEffectMultiverse span,
  .homepageEffectLayer.is-black-symbiote::before,
  .homepageEffectLayer.is-black-symbiote::after,
  .homepageAmbientParticle.is-black-symbiote,
  .homepageBlackSpider,
  .homepageSpiderWeb,
  .homepageSpiderThread,
  .homepageEffectFlood { animation-duration: 40s !important; }
  .homepageFloodWave, .homepageFloodShine { animation-duration: 14s !important; }
}


