/* SOLAR SYSTEM: all planets, orbiting, interactive parallax */
.homepageEffectLayer.is-solar-system{--solar-pointer-x:0px;--solar-pointer-y:0px}
.homepageEffectLayer.is-solar-system .homepageEffectBackdrop{background:radial-gradient(circle at 28% 45%,rgba(78,115,185,.12),transparent 28%),radial-gradient(circle at 82% 22%,rgba(116,52,165,.13),transparent 24%),linear-gradient(180deg,rgba(1,5,20,.84),rgba(2,8,28,.92));backdrop-filter:brightness(.54) saturate(.98)}
.homepageSolarSystemScene{background:radial-gradient(circle at 50% 50%,rgba(70,106,188,.05),transparent 44%);pointer-events:auto}
.homepageSolarSystemScene .solarSceneGlow{position:absolute;inset:auto;width:34vw;height:34vw;max-width:520px;max-height:520px;border-radius:50%;filter:blur(42px);opacity:.24;animation:solarGlowPulse 12s ease-in-out infinite alternate}
.homepageSolarSystemScene .glow-a{left:-8%;top:2%;background:radial-gradient(circle,#4fb9ff 0,rgba(79,185,255,.22) 38%,transparent 72%)}
.homepageSolarSystemScene .glow-b{right:-10%;bottom:-6%;background:radial-gradient(circle,#8843ff 0,rgba(136,67,255,.18) 34%,transparent 72%);animation-delay:-5.4s}
.homepageSolarSystemScene .solarSystemStage{position:absolute;left:50%;top:52%;width:min(96vw,1700px);height:min(90vh,980px);translate:-50% -50%;transform:translate(calc(var(--solar-pointer-x)*.36),calc(var(--solar-pointer-y)*.36));transform-style:preserve-3d;transition:transform .22s ease-out}
.homepageSolarSystemScene .solarSun{position:absolute;left:20%;top:50%;translate:-50% -50%;width:clamp(98px,9vw,168px);aspect-ratio:1;border-radius:50%;z-index:5;filter:drop-shadow(0 0 38px rgba(255,168,44,.46))}
