.homepageSolarSystemScene .solarSunAura{inset:-30%;background:radial-gradient(circle,rgba(255,223,109,.58),rgba(255,154,23,.22) 38%,rgba(255,120,0,.04) 64%,transparent 72%);animation:solarSunPulse 7.4s ease-in-out infinite alternate}
.homepageSolarSystemScene .solarSunCore{background:radial-gradient(circle at 34% 34%,#fff8d1 0 11%,#ffd667 20%,#ffba35 46%,#ff8914 72%,#d45600 100%);box-shadow:0 0 22px rgba(255,204,97,.9),0 0 65px rgba(255,132,22,.6),inset -16px -10px 20px rgba(146,49,0,.34)}
.homepageSolarSystemScene .solarSun::after{content:"Sun";position:absolute;left:50%;top:calc(100% + 10px);translate:-50% 0;padding:4px 10px;border-radius:999px;background:rgba(8,12,22,.72);border:1px solid rgba(255,226,134,.26);color:#ffe8a1;font:700 12px/1 Arial,sans-serif;letter-spacing:.05em;text-transform:uppercase;white-space:nowrap}
.homepageSolarSystemScene .solarOrbit{position:absolute;left:20%;top:50%;translate:-50% -50%;width:var(--orbit);height:calc(var(--orbit)*.64);border:1px solid rgba(175,203,255,.16);border-radius:50%;animation:solarOrbitSpin var(--duration) linear infinite;animation-delay:var(--delay);transform-origin:center center}
.homepageSolarSystemScene .orbit-mercury{--orbit:min(16vw,250px);--duration:9s;--delay:-1.8s}
.homepageSolarSystemScene .orbit-venus{--orbit:min(23vw,360px);--duration:13s;--delay:-4s}
.homepageSolarSystemScene .orbit-earth{--orbit:min(31vw,500px);--duration:18s;--delay:-6.4s}
