.homepageSolarSystemScene .orbit-uranus{--orbit:min(79vw,1280px);--duration:57s;--delay:-31s}
.homepageSolarSystemScene .orbit-neptune{--orbit:min(92vw,1490px);--duration:71s;--delay:-44s}
.homepageSolarSystemScene .solarPlanetAnchor{position:absolute;left:100%;top:50%;translate:-50% -50%;display:grid;place-items:center;width:max(30px,var(--size,30px));height:max(30px,var(--size,30px));pointer-events:auto}
.homepageSolarSystemScene .solarPlanet{position:relative;display:block;width:var(--size);height:var(--size);border-radius:50%;box-shadow:0 0 16px rgba(255,255,255,.18), inset -6px -5px 10px rgba(0,0,0,.28);cursor:pointer;transition:transform .2s ease,filter .2s ease}
.homepageSolarSystemScene .solarPlanet::after{content:attr(data-name);position:absolute;left:50%;top:calc(100% + 9px);translate:-50% 0;padding:3px 8px;border-radius:999px;background:rgba(4,10,22,.82);border:1px solid rgba(183,207,255,.20);color:#edf5ff;font:700 11px/1 Arial,sans-serif;letter-spacing:.04em;white-space:nowrap;opacity:0;transform:translateY(6px);transition:opacity .18s ease,transform .18s ease;pointer-events:none}
.homepageSolarSystemScene .solarPlanet:hover,.homepageSolarSystemScene .solarPlanet:focus-visible{transform:scale(1.2);filter:brightness(1.12) saturate(1.1)}
