/* =========================================================
   v452 PICTURE STORY PROGRESS — CENTERED FULL SCREEN WIDTH
   Equal left/right margins on desktop and phone. The segmented
   IG/FB-style timer spans almost the entire viewport width.
========================================================= */
.homepageEffectLayer.is-picture .homepageEffectStoryProgress {
  top: max(8px, env(safe-area-inset-top)) !important;
  left: max(10px, env(safe-area-inset-left)) !important;
  right: max(10px, env(safe-area-inset-right)) !important;
  width: auto !important;
  max-width: none !important;
  margin: 0 !important;
  transform: none !important;
  gap: clamp(3px, .45vw, 6px) !important;
  height: 4px !important;
  z-index: 19 !important;
}
.homepageEffectLayer.is-picture .homepageEffectStorySegment {
  min-width: 0 !important;
}
@media (max-width:700px) {
  .homepageEffectLayer.is-picture .homepageEffectStoryProgress {
    top: max(7px, env(safe-area-inset-top)) !important;
    left: max(7px, env(safe-area-inset-left)) !important;
    right: max(7px, env(safe-area-inset-right)) !important;
    gap: 3px !important;
    height: 3px !important;
  }
}

/* Keep the plain white X below the story timer so the last progress segment
   stays completely visible across the full width. */
.homepageEffectLayer.is-picture .homepageEffectClose {
  top: max(20px, calc(env(safe-area-inset-top) + 12px)) !important;
}
@media (max-width:700px) {
  .homepageEffectLayer.is-picture .homepageEffectClose {
    top: max(18px, calc(env(safe-area-inset-top) + 10px)) !important;
  }
}


/* =========================================================
   v453 HARD RUNTIME-COMPANION OVERRIDES
   Story timer is viewport-wide, not panel-relative.
========================================================= */
.homepageEffectLayer.is-picture #homepageEffectStoryProgress.homepageEffectStoryProgress{
  position:fixed!important;
  top:max(7px,env(safe-area-inset-top))!important;
  left:0!important;
  right:auto!important;
  width:100vw!important;
  max-width:100vw!important;
  box-sizing:border-box!important;
  padding-left:max(8px,env(safe-area-inset-left))!important;
  padding-right:max(8px,env(safe-area-inset-right))!important;
  margin:0!important;
  transform:none!important;
  display:flex!important;
  justify-content:center!important;
  gap:5px!important;
  height:4px!important;
  z-index:2147483646!important;
  pointer-events:none!important;
}
.homepageEffectLayer.is-picture #homepageEffectStoryProgress[hidden]{display:none!important}
.homepageEffectLayer.is-picture #homepageEffectStoryProgress .homepageEffectStorySegment{flex:1 1 0!important;min-width:0!important;height:100%!important}
.homepageEffectLayer.is-picture .homepageEffectClose{top:max(19px,calc(env(safe-area-inset-top) + 12px))!important;right:max(10px,env(safe-area-inset-right))!important}
