/* =========================================================
   v479 — SFK #BeKind Wall themed chrome + universal note readability
   The wall badge, Add Note button, and global close button now follow the
   active wall theme. Every note receives a contrast-safe rendered text color.
========================================================= */
.homepageFreedomWallScene{
  --fw-ui-bg:rgba(255,255,255,.94);
  --fw-ui-fg:#171717;
  --fw-ui-muted:#5b6168;
  --fw-ui-border:rgba(0,0,0,.14);
  --fw-ui-accent:#f4c928;
  --fw-ui-accent-fg:#171717;
  --fw-ui-shadow:0 10px 22px rgba(0,0,0,.18);
  --fw-ui-radius:13px;
  --fw-ui-font:Arial,sans-serif;
  --fw-ui-border-width:1px;
}
.homepageFreedomWallScene .freedomWallBrand{
  background:var(--fw-ui-bg)!important;color:var(--fw-ui-fg)!important;
  border:var(--fw-ui-border-width) solid var(--fw-ui-border)!important;
  border-radius:var(--fw-ui-radius)!important;box-shadow:var(--fw-ui-shadow)!important;
  backdrop-filter:blur(7px);-webkit-backdrop-filter:blur(7px);
}
.homepageFreedomWallScene .freedomWallBrand strong{color:var(--fw-ui-fg)!important;font-family:var(--fw-ui-font)!important}
.homepageFreedomWallScene .freedomWallBrand span{color:var(--fw-ui-muted)!important;font-family:var(--fw-ui-font)!important}
.homepageFreedomWallScene .freedomWallAddBtn{
  background:var(--fw-ui-bg)!important;color:var(--fw-ui-fg)!important;
  border:var(--fw-ui-border-width) solid var(--fw-ui-border)!important;
  border-radius:999px!important;box-shadow:var(--fw-ui-shadow)!important;
  font-family:var(--fw-ui-font)!important;
}
.homepageFreedomWallScene .freedomWallAddBtn span{
  background:var(--fw-ui-accent)!important;color:var(--fw-ui-accent-fg)!important;
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--fw-ui-border) 70%,transparent)!important;
}
.homepageFreedomWallScene .freedomWallAddBtn small{color:var(--fw-ui-fg)!important;font-family:var(--fw-ui-font)!important}
.homepageFreedomWallScene .freedomWallAddBtn:hover,
.homepageFreedomWallScene .freedomWallAddBtn:focus-visible{transform:translateY(-2px);outline:2px solid color-mix(in srgb,var(--fw-ui-accent) 68%,#fff 32%);outline-offset:2px}

